    this.shipS = rndSphere(rnd); this.shipD = anyTang(this.shipS); { const a = rnd() * 6.2832; this.shipD = norm(add(mul(this.shipD, Math.cos(a)), cross(this.shipS, this.shipD), Math.sin(a))); }
